#nullable enable // autogenerated

using MVZ2.GameContent.Buffs.Level;
using MVZ2.GameContent.Effects;
using MVZ2.GameContent.Entities;
using MVZ2.GameContent.Pickups;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Buffs;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Models;

namespace MVZ2.GameContent.Contraptions
{
    [AutoEntityBehaviourDefinition(VanillaContraptionNames.loanSign)]
    public class LoanSign : AIEntityBehaviour
    {
        public LoanSign(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            var lendCount = GetLendCount(entity);
            for (int i = 0; i < lendCount; i++)
            {
                entity.Spawn(VanillaPickupID.starshard, entity.GetCenter());
            }
        }
        protected override void UpdateLogic(Entity entity)
        {
            base.UpdateLogic(entity);
            entity.SetModelProperty("RepaidCount", GetRepaidCount(entity));
        }
        public override void PostDeath(Entity entity, DeathInfo deathInfo)
        {
            base.PostDeath(entity, deathInfo);
            var repayCount = GetRepaidCount(entity);
            if (repayCount < GetMaxRepayCount(entity))
            {
                var disableSeconds = GetDisableSeconds(entity, repayCount);
                var buff = entity.Level.NewBuff<LoanSignStarshardDisableBuff>();
                LoanSignStarshardDisableBuff.SetSeconds(buff, disableSeconds);
                entity.Level.AddBuff(buff);

                entity.Level.PlaySound(VanillaSoundID.locked);
            }
        }
        public static float GetDisableSeconds(Entity entity, int repayCount)
        {
            switch (repayCount)
            {
                case 1:
                    return entity.GetProperty<float>(PROP_DISABLE_SECONDS_1);
                case 2:
                    return entity.GetProperty<float>(PROP_DISABLE_SECONDS_2);
                case 3:
                default:
                    return entity.GetProperty<float>(PROP_DISABLE_SECONDS_3);
            }
        }
        public static void Repay(Entity entity, int count = 1)
        {
            int value = GetRepaidCount(entity) + count;
            SetRepaidCount(entity, value);
            if (value >= GetMaxRepayCount(entity))
            {
                entity.SpawnWithParams(VanillaEffectID.smokeCluster, entity.GetCenter());
                entity.Remove();
            }
        }
        public static int GetLendCount(Entity entity) => entity.GetBehaviourField<int>(PROP_LEND_COUNT);
        public static void SetLendCount(Entity entity, int value) => entity.SetBehaviourField(PROP_LEND_COUNT, value);
        public static int GetMaxRepayCount(Entity entity) => entity.GetBehaviourField<int>(PROP_MAX_REPAY_COUNT);
        public static void SetMaxRepayCount(Entity entity, int value) => entity.SetBehaviourField(PROP_MAX_REPAY_COUNT, value);
        public static int GetRepaidCount(Entity entity) => entity.GetBehaviourField<int>(PROP_REPAID_COUNT);
        public static void SetRepaidCount(Entity entity, int value) => entity.SetBehaviourField(PROP_REPAID_COUNT, value);
        public static readonly VanillaEntityPropertyMeta<int> PROP_LEND_COUNT = new VanillaEntityPropertyMeta<int>("lend_count", 2);
        public static readonly VanillaEntityPropertyMeta<int> PROP_MAX_REPAY_COUNT = new VanillaEntityPropertyMeta<int>("max_repay_count", 3);
        public static readonly VanillaEntityPropertyMeta<int> PROP_REPAID_COUNT = new VanillaEntityPropertyMeta<int>("repaied_count");
        public static readonly VanillaEntityPropertyMeta<float> PROP_DISABLE_SECONDS_1 = new VanillaEntityPropertyMeta<float>("disable_seconds_1", 30f);
        public static readonly VanillaEntityPropertyMeta<float> PROP_DISABLE_SECONDS_2 = new VanillaEntityPropertyMeta<float>("disable_seconds_2", 60f);
        public static readonly VanillaEntityPropertyMeta<float> PROP_DISABLE_SECONDS_3 = new VanillaEntityPropertyMeta<float>("disable_seconds_3", 120f);
    }
}
